import{_ as l,C as h,o as g,c as o,j as e,a as t,E as c,a2 as a}from"./chunks/framework.CQjSGuJt.js";const y=JSON.parse('{"title":"7. Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/changelog.md","filePath":"gdd/changelog.md"}'),r={name:"gdd/changelog.md"},d={id:"latest-main",tabindex:"-1"};function s(u,n,m,v,x,p){const i=h("Badge");return g(),o("div",null,[n[3]||(n[3]=e("h1",{id:"_7-changelog",tabindex:"-1"},[t("7. Changelog "),e("a",{class:"header-anchor",href:"#_7-changelog","aria-label":'Permalink to "7. Changelog"'},"​")],-1)),n[4]||(n[4]=e("p",null,[t("Every published version stays playable at its own URL. The "),e("a",{href:"https://huykc1.github.io/fish-loop-phaser-demo/",target:"_blank",rel:"noreferrer"},"landing page"),t(" lists them all.")],-1)),e("h2",d,[n[0]||(n[0]=t("latest (main) ",-1)),c(i,{type:"tip",text:"Live"}),n[1]||(n[1]=t()),n[2]||(n[2]=e("a",{class:"header-anchor",href:"#latest-main","aria-label":'Permalink to "latest (main) <Badge type="tip" text="Live" />"'},"​",-1))]),n[5]||(n[5]=a('<ul><li>Project scaffold.</li><li>Gameplay Fish Bus chạy trên Phaser 4, 5 level, asset cắt từ ảnh mẫu, animation và hiệu ứng.</li><li>Xe dọc có ảnh riêng cho 2 chiều (đầu xuống / đuôi xuống).</li><li>Bể nước vẽ lại theo từng màu (khối nước phát sáng, viền kính ánh màu).</li><li>Ống hở có 2 cổng (<code>pipe.open</code>), cỡ xe theo level (<code>busScale</code>), xe hoàn thành đóng nắp + ✓. Level 6 &quot;Hai cổng&quot;.</li><li>Bỏ mũi tên làn ở 2 đầu xe ngang.</li><li>Kiểm tra mới: xe / chỗ dự phòng không được đè lên ống (editor báo lỗi, chỗ dự phòng tự động cũng tránh, có test). Sửa level 6 (2 hàng xe lấn vào ống), level 2 (xe dọc sát ống trái, chỗ dự phòng sát ống trên; cỡ xe 0,95), level 9 (2 xe trong lòng ống chạm nhau).</li><li>Thêm level 7–10 theo 4 bố cục mẫu (<code>art/reference/layout-ref-7..10.jpg</code>): Chữ S (ống S hở, 3 hàng xe), Móc câu (ống ⊃ hở, xe trên / trong / dưới), Hai bờ (vòng ngang, 2 xe trong + xe 2 bờ), Ô vuông (vòng vuông, 3 xe trong + xe trên / dưới). 8–10 màu, màu rải theo cặp; solver giải được tất cả.</li><li>Bảng màu từ 8 lên 15 màu (7 cá mới tạo bằng ChatGPT); nền bãi tự mở rộng khi có xe nằm ngoài ống; bảng chọn level trong Cài đặt thành 2 hàng.</li><li>Nền bãi xe đổi sang xanh dương đậm theo ảnh mẫu, phủ vân sóng nước động (chỉ trong lòng bãi); xe có bóng đổ mềm lệch xuống dưới như ảnh mẫu.</li><li>Solver mới tìm lời giải ngắn về thời gian chơi (trước đây tìm sâu, hay tap lặp một xe và chờ cả vòng): level 6 từ 43 tap / ~13 phút còn 23 tap / ~1 phút; level 5 từ 46 tap / ~16 phút còn 17 tap / ~32 giây.</li><li>Level 6 thiết kế lại: 7 xe đầy (7 màu × 4 nấc, không xe trống), cỡ xe 0,7, hàng trên 4 xe + hàng dưới 3 xe và chỗ dự phòng; solver giải được (43 lần tap).</li><li>Chỗ dự phòng phải nối thẳng vào ống (editor báo lỗi nếu không). Level 6 dàn lại: cỡ xe 0,55, hàng dưới 6 chỗ, xe dự phòng là chỗ thứ 6 (đuôi xuống ống dưới); solver xác nhận vẫn giải được.</li><li>Cổng tự động của xe đổi thành điểm gặp ống khi đi thẳng từ đuôi xe (trước đây là điểm gần nhất, nên xe sát mép trên bị lấy cổng ở đoạn ống phía trên). Solver xác nhận 6 level vẫn giải được.</li><li>Sửa xe xoay 180° (đuôi bên trái): thân xe chỉ lật ngang, bể nằm đúng trong khay (trước đây bể bị tụt xuống dưới); bóng mờ xe dự phòng đúng chiều xe thật (không lộn ngược). Áp dụng cho game, editor và bàn tay hướng dẫn.</li><li>Mỗi level có sẵn vị trí xe dự phòng (máy tự đặt) và ít nhất 1 lượt Thêm xe. Level 1, 4, 5 dàn lại cột xe để có chỗ (level 4, 5 thu cỡ xe còn 0,87); solver xác nhận 6 level vẫn giải được.</li><li>Luật cá vào xe: nấc ưu tiên xe có đuôi cùng màu, bỏ qua xe trống cho tới khi xe đó đầy (tránh 2 xe chuyền nấc qua lại). Solver xác nhận 6 level vẫn giải được.</li><li>Level Editor ở <code>/editor/</code> theo spec <code>docs/guide/editor.md</code>: lưu folder / browser storage, 3 bản cũ, nháp, Organiser + Add levels, solver và sinh màu chạy ngầm, chơi thử trong editor.</li><li>Dữ liệu level chuyển sang <code>level-data/</code> (levels/, collections/Main/); game đọc collection Main.</li><li>Xem lời giải: bàn tay hướng dẫn (tạo bằng ChatGPT) tự chơi theo solver, tap đúng lịch nên chắc chắn thắng.</li><li>Cá đổi thành bộ 8 cá hề cùng dáng (tạo bằng ChatGPT theo quy trình <code>docs/guide/assets.md</code>).</li><li>Bộ đếm HUD đổi thành số nấc trên ống <code>x/N</code> (N = <code>pipeLimit</code>, mặc định 5); tap bị giới hạn bởi N.</li><li>Booster mới: <strong>Return</strong> (trả nấc vừa vào xe về chỗ cũ), <strong>Shuffle 1 xe</strong> (chọn xe, gom màu, màu lẻ ra đuôi). Bỏ Undo kiểu khôi phục trạng thái và Shuffle màu trong ống.</li><li>Level 4 và 6 sinh lại màu theo luật N = 5 (level 6 còn 7 màu, 4 xe trống); solver xác nhận cả 6 level giải được.</li><li>Sửa solver: bản sao trạng thái giữ đúng bộ đếm kẹt (trước đây có thể coi là giải được ở màn thực tế sẽ thua).</li><li>Level 2: dời 2 xe ngang sang phải cho đuôi xe sát ống (x 540 → 655).</li><li>Xe cố định 4 nấc; level 4 sinh lại màu cho xe 4 nấc (solver xác nhận giải được); level 3 giãn lại khoảng cách xe để không chồng lên vị trí dự phòng.</li></ul><p><a href="https://huykc1.github.io/fish-loop-phaser-demo/demo/" target="_blank" rel="noreferrer">Play latest</a></p><h2 id="document-history" tabindex="-1">Document history <a class="header-anchor" href="#document-history" aria-label="Permalink to &quot;Document history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>2026-10-23</td><td>GDD created</td></tr></tbody></table>',4))])}const f=l(r,[["render",s]]);export{y as __pageData,f as default};
